CREATE TRIGGER IF NOT EXISTS locked_report_update BEFORE UPDATE ON reports WHEN OLD.finalised_at IS NOT NULL BEGIN SELECT RAISE(ABORT,'Finalised report is locked'); END;
CREATE TRIGGER IF NOT EXISTS locked_room_insert BEFORE INSERT ON room_entries WHEN (SELECT finalised_at FROM reports WHERE id=NEW.report_id) IS NOT NULL BEGIN SELECT RAISE(ABORT,'Finalised report is locked'); END;
CREATE TRIGGER IF NOT EXISTS locked_room_update BEFORE UPDATE ON room_entries WHEN (SELECT finalised_at FROM reports WHERE id=OLD.report_id) IS NOT NULL OR (SELECT finalised_at FROM reports WHERE id=NEW.report_id) IS NOT NULL BEGIN SELECT RAISE(ABORT,'Finalised report is locked'); END;
CREATE TRIGGER IF NOT EXISTS locked_room_delete BEFORE DELETE ON room_entries WHEN (SELECT finalised_at FROM reports WHERE id=OLD.report_id) IS NOT NULL BEGIN SELECT RAISE(ABORT,'Finalised report is locked'); END;
CREATE TRIGGER IF NOT EXISTS locked_photo_insert BEFORE INSERT ON photos WHEN EXISTS(SELECT 1 FROM room_entries r JOIN reports p ON p.id=r.report_id WHERE r.id=NEW.room_entry_id AND p.finalised_at IS NOT NULL) BEGIN SELECT RAISE(ABORT,'Finalised report is locked'); END;
CREATE TRIGGER IF NOT EXISTS locked_photo_update BEFORE UPDATE ON photos WHEN EXISTS(SELECT 1 FROM room_entries r JOIN reports p ON p.id=r.report_id WHERE r.id IN (OLD.room_entry_id,NEW.room_entry_id) AND p.finalised_at IS NOT NULL) BEGIN SELECT RAISE(ABORT,'Finalised report is locked'); END;
CREATE TRIGGER IF NOT EXISTS locked_photo_delete BEFORE DELETE ON photos WHEN EXISTS(SELECT 1 FROM room_entries r JOIN reports p ON p.id=r.report_id WHERE r.id=OLD.room_entry_id AND p.finalised_at IS NOT NULL) BEGIN SELECT RAISE(ABORT,'Finalised report is locked'); END;
CREATE TRIGGER IF NOT EXISTS immutable_addendum BEFORE UPDATE ON addenda BEGIN SELECT RAISE(ABORT,'Addenda cannot be edited'); END;
